package pilot

import java.io.IOException
import java.net.SocketTimeoutException
import java.util.UUID
import java.util.concurrent.Callable
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicInteger
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotEquals
import org.junit.jupiter.api.Assertions.assertSame
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class PaymentServiceReviewTest {
    enum class Step { OK, IO_BEFORE_DEBIT, IO_AFTER_DEBIT, REJECT }

    /** Atomically deduplicates by key; [plan] decides the outcome of each physical call. */
    class FakeGateway(private val plan: (callNo: Int) -> Step = { Step.OK }) : PaymentGateway {
        val keys = mutableListOf<String>()
        val debits = linkedMapOf<String, Receipt>()
        val lastThrown = mutableListOf<Throwable>()

        @Synchronized
        override fun charge(request: Charge, idempotencyKey: String): Receipt {
            keys += idempotencyKey
            val step = plan(keys.size)
            if (step == Step.REJECT) throw RejectedCharge().also { lastThrown += it }
            if (step == Step.IO_BEFORE_DEBIT) throw IOException("before debit").also { lastThrown += it }
            val receipt = debits.getOrPut(idempotencyKey) { Receipt("r-${debits.size + 1}") }
            if (step == Step.IO_AFTER_DEBIT) throw SocketTimeoutException("response lost").also { lastThrown += it }
            return receipt
        }
    }

    private fun seqKeys(): () -> String {
        val n = AtomicInteger()
        return { "k-${n.incrementAndGet()}" }
    }

    private val req = Charge("acc-1", 1000)

    @Test fun `lost response after debit is retried with same key and debits once`() {
        val gw = FakeGateway { if (it == 1) Step.IO_AFTER_DEBIT else Step.OK }
        val receipt = PaymentService(gw, seqKeys()).charge(req)
        assertEquals(Receipt("r-1"), receipt)
        assertEquals(1, gw.debits.size)
        assertEquals(listOf("k-1", "k-1"), gw.keys)
    }

    @Test fun `two lost responses then success - three attempts, one debit`() {
        val gw = FakeGateway { if (it <= 2) Step.IO_AFTER_DEBIT else Step.OK }
        assertEquals(Receipt("r-1"), PaymentService(gw, seqKeys()).charge(req))
        assertEquals(1, gw.debits.size)
        assertEquals(listOf("k-1", "k-1", "k-1"), gw.keys)
    }

    @Test fun `io before debit then success - one debit`() {
        val gw = FakeGateway { if (it == 1) Step.IO_BEFORE_DEBIT else Step.OK }
        assertEquals(Receipt("r-1"), PaymentService(gw, seqKeys()).charge(req))
        assertEquals(1, gw.debits.size)
        assertEquals(2, gw.keys.size)
    }

    @Test fun `three IOExceptions - exactly three attempts and last exception rethrown`() {
        val gw = FakeGateway { Step.IO_AFTER_DEBIT }
        val thrown = assertThrows(IOException::class.java) { PaymentService(gw, seqKeys()).charge(req) }
        assertSame(gw.lastThrown.last(), thrown)
        assertEquals(listOf("k-1", "k-1", "k-1"), gw.keys)
        assertEquals(1, gw.debits.size)
    }

    @Test fun `rejected charge is not retried`() {
        val gw = FakeGateway { Step.REJECT }
        assertThrows(RejectedCharge::class.java) { PaymentService(gw, seqKeys()).charge(req) }
        assertEquals(1, gw.keys.size)
        assertEquals(0, gw.debits.size)
    }

    @Test fun `rejected after IOException is not retried`() {
        val gw = FakeGateway { if (it == 1) Step.IO_BEFORE_DEBIT else Step.REJECT }
        assertThrows(RejectedCharge::class.java) { PaymentService(gw, seqKeys()).charge(req) }
        assertEquals(2, gw.keys.size)
        assertEquals(0, gw.debits.size)
    }

    @Test fun `other runtime exceptions propagate without retry`() {
        var calls = 0
        val svc = PaymentService({ _, _ -> calls++; throw IllegalStateException("boom") }, seqKeys())
        assertThrows(IllegalStateException::class.java) { svc.charge(req) }
        assertEquals(1, calls)
    }

    @Test fun `newKey failure propagates and gateway is not called`() {
        var calls = 0
        val svc = PaymentService({ _, _ -> calls++; Receipt("x") }, { throw IllegalStateException("no key") })
        assertThrows(IllegalStateException::class.java) { svc.charge(req) }
        assertEquals(0, calls)
    }

    @Test fun `separate calls with identical data are separate payments`() {
        val gw = FakeGateway { if (it % 2 == 1) Step.IO_AFTER_DEBIT else Step.OK }
        val keyCalls = AtomicInteger()
        val svc = PaymentService(gw) { keyCalls.incrementAndGet(); UUID.randomUUID().toString() }
        val r1 = svc.charge(Charge("acc-1", 1000))
        val r2 = svc.charge(Charge("acc-1", 1000))
        assertNotEquals(r1, r2)
        assertEquals(2, gw.debits.size)
        assertEquals(2, keyCalls.get())
        assertEquals(gw.keys[0], gw.keys[1])
        assertEquals(gw.keys[2], gw.keys[3])
        assertNotEquals(gw.keys[0], gw.keys[2])
    }

    @Test fun `concurrent calls each produce exactly one debit`() {
        val n = 200
        val gw = FakeGateway { if (it % 3 != 0) Step.IO_AFTER_DEBIT else Step.OK }
        val svc = PaymentService(gw) { UUID.randomUUID().toString() }
        val pool = Executors.newFixedThreadPool(16)
        val results = pool.invokeAll((1..n).map { Callable { runCatching { svc.charge(req) } } }).map { it.get() }
        pool.shutdown()
        assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS))
        // every logical payment either succeeded or exhausted its attempts; none was debited twice
        assertEquals(n, gw.keys.toSet().size)
        assertEquals(n, gw.debits.size)
        val ok = results.filter { it.isSuccess }.map { it.getOrThrow() }
        assertEquals(ok.size, ok.toSet().size)
        results.filter { it.isFailure }.forEach { assertTrue(it.exceptionOrNull() is IOException) }
        gw.keys.groupingBy { it }.eachCount().values.forEach { assertTrue(it in 1..3) }
    }
}

